import java.io.*;
import java.util.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        boolean neg = c == '-';
        if (neg) c = read();
        long r = 0;
        while (c >= '0' && c <= '9') {
            r = r * 10 + (c - '0');
            c = read();
        }
        return neg ? -r : r;
    }

    // number of elements < x (strict) or <= x (inclusive) in sorted a
    static int bound(long[] a, long x, boolean inclusive) {
        int lo = 0, hi = a.length;
        while (lo < hi) {
            int mid = (lo + hi) >>> 1;
            if (a[mid] < x || (inclusive && a[mid] == x)) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    public static void main(String[] args) throws IOException {
        int n = (int) nextLong(), q = (int) nextLong();
        long[] l = new long[n], r = new long[n];
        for (int i = 0; i < n; i++) {
            l[i] = nextLong();
            r[i] = nextLong();
        }
        Arrays.sort(l);
        Arrays.sort(r);
        StringBuilder out = new StringBuilder();
        for (int i = 0; i < q; i++) {
            long p = nextLong();
            if (i > 0) out.append(' ');
            // lamps starting at or before p, minus lamps that already ended before p
            out.append(bound(l, p, true) - bound(r, p, false));
        }
        System.out.println(out);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"sort"
	"strconv"
)

var data []byte
var pos int

func nextInt() int64 {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	neg := false
	if pos < len(data) && data[pos] == '-' {
		neg = true
		pos++
	}
	var r int64
	for pos < len(data) && data[pos] >= '0' && data[pos] <= '9' {
		r = r*10 + int64(data[pos]-'0')
		pos++
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, q := int(nextInt()), int(nextInt())
	l, r := make([]int64, n), make([]int64, n)
	for i := 0; i < n; i++ {
		l[i], r[i] = nextInt(), nextInt()
	}
	slices.Sort(l)
	slices.Sort(r)
	out := []byte{}
	for i := 0; i < q; i++ {
		p := nextInt()
		// lamps starting at or before p, minus lamps that already ended before p
		started := sort.Search(n, func(j int) bool { return l[j] > p })
		ended := sort.Search(n, func(j int) bool { return r[j] >= p })
		if i > 0 {
			out = append(out, ' ')
		}
		out = strconv.AppendInt(out, int64(started-ended), 10)
	}
	out = append(out, '\n')
	os.Stdout.Write(out)
}
